'use strict';
const C=TP, STORE='truongphat-quotation-v2';
let db=TPPrice.demoSeed(),page='quote',tab='bom',selected='',catalogGroup='',search='',libraryFilter='all',rateTab='materials',restored=false;
try{const saved=JSON.parse(localStorage.getItem(STORE));if(saved?.version===2&&saved.quote?.products&&saved.materials){db=saved;restored=true;}}catch{}
selected=db.quote.products[0]?.id;
let result=C.calculate(db),undoState=null,rotation={x:-20,y:-30},modalReturn=null;
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>TPDisplay.money(n),num=(n,d)=>TPDisplay.number(n,d);
const btn=(text,action,attr='',style='')=>`<button class="button ${style}" data-action="${action}" ${attr}>${text}</button>`;
const empty=(title,copy,action='')=>`<div class="empty"><span class="empty-symbol">◇</span><h3>${title}</h3><p>${copy}</p>${action}</div>`;
const field=(label,name,value,type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value,extra='')=>`<label class="field"><span>${label}</span><select name="${name}" ${extra}>${options.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(db));$('#save-status').textContent='Đã lưu trên máy';}catch{$('#save-status').textContent='Chưa lưu được trên máy';toast('Bộ nhớ trình duyệt đầy. Hãy sao lưu dữ liệu.');}}
function mutation(action,options={}){undoState=C.copy(db);UX.undo.push(undoState);if(UX.undo.length>30)UX.undo.shift();UX.redo=[];try{action();}catch(e){db=UX.undo.pop();throw e;}if(options.preserveQuote)db.quote=C.copy(undoState.quote);for(const n of C.flatten(db.quote.products))if(n.kind==='product'){if(n.params)for(const [k,v]of Object.entries(n.params))C.applyParam(n,k,v);C.formatName(n);}if(C.flatten(db.quote.products).some(n=>Object.keys(n.dimensionLinks||{}).length))TPDimensions.resolve(db.quote.products);if(!current())selected=db.quote.products[0]?.id;UX.checked=new Set([...UX.checked].filter(id=>C.findNode(db.quote.products,id)));if(!options.preserveQuote)db.quote.status='draft';b2Identity();persist();if(options.soft)refreshQuickUI();else render();}
function current(){return C.findNode(db.quote.products,selected);}
function dimensionName(k,m){return ({L:'Dài',W:'Rộng',H:'Cao',T:'Dày',TF:'Dày cánh',D:'Đường kính',F:'Mép'})[k]||m?.shapeDefinition?.fields?.find(f=>f.key===k)?.name||k;}
function specText(m){if(m.shapeDefinition)return [m.substance,m.grade,m.shapeDefinition.name,...m.shapeDefinition.fields.filter(f=>f.mode==='fixed').map(f=>dimensionName(f.key,m)+' '+num(m.props[f.key])+' '+f.unit)].filter(Boolean).join(' / ');const p=m.props;return [m.substance,m.grade,C.shapeInfo(m).name,...Object.entries(p).map(([k,v])=>`${dimensionName(k,m)} ${num(v)} mm`)].join(' / ');}
// View-only memory: never saved into the quote or its undo history.
const treeViewport={saved:null};
function captureTreeViewport(){
  const tree=$('.tree-body');if(!tree)return null;
  const top=tree.getBoundingClientRect().top,rows=[...tree.querySelectorAll('[data-select]')];
  // Stable row anchors also survive insertion/removal above the visible area.
  const anchors=rows.map(row=>({id:row.dataset.select,offset:row.getBoundingClientRect().top-top,bottom:row.getBoundingClientRect().bottom-top}));
  treeViewport.saved={left:tree.scrollLeft,anchors:[...anchors.filter(row=>row.bottom>0),...anchors.filter(row=>row.bottom<=0).reverse()]};
  return {x:scrollX,y:scrollY,focus:tree.contains(document.activeElement)?document.activeElement.dataset.select:null};
}
function restoreTreeViewport(previous){
  const tree=$('.tree-body'),saved=treeViewport.saved;if(!tree||!saved)return;
  const rows=new Map([...tree.querySelectorAll('[data-select]')].map(row=>[row.dataset.select,row]));
  const anchor=saved.anchors.find(item=>rows.has(item.id));
  if(anchor)tree.scrollTop+=rows.get(anchor.id).getBoundingClientRect().top-tree.getBoundingClientRect().top-anchor.offset;
  tree.scrollLeft=saved.left;
  if(previous){rows.get(previous.focus)?.focus({preventScroll:true});window.scrollTo(previous.x,previous.y);}
}
function restoreQuoteTabs(left){
  const bar=$('.workspace-tabs'),active=bar?.querySelector('[aria-selected=true]');if(!active)return;
  bar.scrollLeft=left;
  const bounds=bar.getBoundingClientRect(),item=active.getBoundingClientRect();
  // Only move the horizontal strip, never scroll the entire document to the tab.
  if(item.right>bounds.right)bar.scrollLeft+=item.right-bounds.right+8;
  else if(item.left<bounds.left)bar.scrollLeft+=item.left-bounds.left-8;
}
// Keep the matrix viewport through full renders, including modal saves and catalog refreshes.
function installOperationViewport(){
 const previous=render;render=(...args)=>{const view=captureOperationViewport();const value=previous(...args);restoreOperationViewport(view);return value;};
}
function captureOperationViewport(){
 const el=document.querySelector('[data-operation-quote]');
 if(page!=='quote'||tab!=='operations'||!el||el.dataset.operationQuote!==db.quote.id)return null;
 return {quote:db.quote.id,left:el.scrollLeft,top:el.scrollTop,x:window.scrollX,y:window.scrollY};
}
function restoreOperationViewport(view){
 const el=document.querySelector('[data-operation-quote]');
 if(!view||page!=='quote'||tab!=='operations'||el?.dataset.operationQuote!==view.quote)return;
 el.scrollLeft=view.left;el.scrollTop=view.top;window.scrollTo(view.x,view.y);
}
function render(){if(typeof refreshSheetNames==='function')refreshSheetNames();const viewport=captureTreeViewport(),tabsLeft=$('.workspace-tabs')?.scrollLeft||0;result=C.calculate(db);document.body.classList.toggle('quick-entry',page==='quote'&&tab==='bom'&&UX.mode==='quick');document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#page-label').textContent={quote:'Báo giá',materials:'Danh mục vật tư',library:'Thư viện mẫu',rates:'Đơn giá đầu vào',rules:'Danh mục quy ước',customers:'Đầu vào khách hàng'}[page];$('#content').innerHTML=({quote:renderQuote,materials:renderMaterials,library:renderLibrary,rates:renderRates,rules:renderRules,customers:renderCustomers})[page]();if(page==='quote'&&tab==='bom')setup3d();restoreTreeViewport(viewport);restoreQuoteTabs(tabsLeft);}
function renderQuote(){const q=db.quote,t=result.total;
  return heading('Báo giá cơ khí',`<span class="mono">${esc(q.id)}</span> <span class="inline-divider">/</span> ${esc(q.project)}`,`${btn('Lịch sử','history')}${btn('Chỉnh thông tin','quote-info')}${btn('Xuất báo giá ↗','preview','','primary')}`)+
  `<div class="quote-ribbon"><div><span class="badge ${q.status==='approved'?'green':''}">${q.status==='approved'?'Đã duyệt nội bộ':'Bản nháp'}</span><strong>${esc(q.customer)}</strong></div><span>Ngày ${esc(q.date.split('-').reverse().join('/'))} <span class="inline-divider">/</span> Hiệu lực ${q.valid} ngày</span></div>`+
  `<div class="quote-metrics"><div><span>Sản phẩm trong báo giá</span><strong>${q.products.length.toString().padStart(2,'0')}<small>${result.rows.length} dòng vật tư</small></strong></div><div><span>Chi phí dự kiến</span><strong>${money(t.cost)}<small>VNĐ</small></strong></div><div><span>${q.pricing?'Chênh lệch trước thuế':'Lợi nhuận dự kiến'}</span><strong class="${t.profit<0?'pa-negative':'positive'}">${money(t.profit)}<small>${q.pricing?'Chưa phải lợi nhuận ròng':'Biên '+num(q.margin)+'%'}</small></strong></div><div class="highlight"><span>Tổng chào giá sau thuế</span><strong>${q.pricing&&result.errors.length?'Cần rà lại':money(t.grand)}<small>VNĐ</small></strong></div></div>`+
  paIntro()+`<div class="workspace-tabs" role="tablist">${[['intake','Đầu vào báo giá'],['bom','Cấu thành sản phẩm'],...(q.pricing?[['operations','Công đoạn & định mức']]:[]),['waste','Khai triển & hao hụt'],['mass','Khối lượng & diện tích'],['prices','Giá & hệ số'],['pricing','Phân tích giá'],['preview','Bản chào giá']].map(([id,label],i)=>`<button role="tab" aria-selected="${tab===id}" data-tab="${id}" class="${tab===id?'active':''}"><span>${i+1}</span>${label}</button>`).join('')}</div>`+
  (tab==='pricing'?inOperationUnitNotice():'')+
  (result.errors.length&&tab!=='intake'&&!(tab==='bom'&&UX.mode==='quick')?`<div class="notice error"><strong>Cần kiểm tra ${result.errors.length} nội dung</strong><span>${esc(result.errors.slice(0,3).join(' • '))}</span></div>`:'')+
  ({intake:renderIntake,prices:renderQuotePrices,bom:renderBOM,operations:renderOperationMatrix,logistics:renderLogistics,waste:renderWaste,mass:renderMass,pricing:renderPricing,preview:renderPreview})[tab]();
}
function treeNode(n,depth=0){const r=result.nodes[n.id],active=n.id===selected,type=n.kind==='product'?'SP':n.kind==='component'?'CK':'VT';return `<button class="tree-node ${active?'selected':''} depth-${Math.min(depth,3)}" data-select="${n.id}" style="--depth:${Math.min(depth,3)}"><span class="node-icon ${n.kind}">${type}</span><span class="node-copy"><strong>${esc(n.name)}</strong><small>${n.kind==='material'?esc(n.materialId):`${n.children?.length||0} thành phần`} <span>× ${num(n.qty)}</span></small></span>${depth===0?`<span class="tree-price">${money(r?.material+r?.ops)}</span>`:''}</button>${(n.children||[]).map(c=>treeNode(c,depth+1)).join('')}`;}
function renderBOM(){return entrySwitcher()+(UX.mode==='quick'?renderQuickBOM():renderTreeBOM());}
function renderTreeBOM(){const n=current();return `<div class="bom-layout"><section class="panel tree-panel"><div class="panel-head"><div><h2>Cấu thành báo giá</h2><p>Chọn một dòng để xem và chỉnh sửa</p></div>${btn('+','add-product','aria-label="Thêm sản phẩm"','square')}</div><div class="tree-body">${db.quote.products.length?db.quote.products.map(p=>treeNode(p)).join(''):empty('Chưa có sản phẩm','Thêm sản phẩm mới hoặc gọi từ thư viện.')}</div><div class="tree-footer">${btn('+ Thêm sản phẩm','add-product','','wide')}<p>SP Sản phẩm <span>CK Cấu kiện</span> VT Vật tư</p></div></section><section class="detail-panel">${n?renderNode(n):empty('Bắt đầu một báo giá','Thêm sản phẩm và chọn các mã vật tư cấu thành.',btn('+ Thêm sản phẩm','add-product','','primary'))}</section></div>`;}
function renderNode(n){const r=result.nodes[n.id],leaf=n.kind==='material',kind=leaf?'Vật tư':n.kind==='product'?'Sản phẩm':'Cấu kiện';const nodeErrors=r.declarationErrors||[];return `<div class="panel node-header"><div class="node-title"><div><span class="overline">${kind} ${leaf?`/ <span class="mono">${esc(n.materialId)}</span>`:''}</span><h2>${esc(n.name)}</h2>${n.kind==='product'?cvProductButton(n):''}</div><div class="actions">${btn('Nhân bản','duplicate',`data-id="${n.id}"`)}${!leaf?btn('Lưu mẫu','save-template',`data-id="${n.id}"`):''}${btn('×','delete-node',`data-id="${n.id}" aria-label="Xóa ${kind.toLowerCase()}"`,'square danger')}</div></div><div class="inline-form"><label class="field grow"><span>Tên ${kind.toLowerCase()}</span><input data-node-field="name" value="${esc(n.name)}" ${leaf?'readonly':''}></label><label class="field qty-field"><span>${db.quote.products.includes(n)?'Số lượng sản phẩm':'SL / 1 cấp cha'}</span><input type="number" min="0.001" max="5000" step="any" data-node-field="qty" value="${n.qty}"></label><div class="computed-count"><span>Số lượng toàn báo giá</span><strong>${num(r.count)}</strong></div></div></div>`+
  (nodeErrors.length?`<div class="node-error-banner">${nodeErrors.map(e=>`<div class="node-error-item">⚠ ${esc(e)}</div>`).join('')}</div>`:'')+
  (leaf?`<div class="detail-split material-3d-split">${renderMaterialDetail(n)}<div class="panel visual-panel">${viewer(n)}</div></div>`:`<div class="detail-split"><div class="panel"><div class="panel-head"><div><h2>Thành phần cấu tạo</h2><p>${n.kind==='product'?'Thêm cấu kiện, vật tư hoặc sản phẩm mẫu':'Một cấu kiện có thể dùng nhiều mã vật tư'}</p></div></div><div class="children-list">${(n.children||[]).map(c=>`<button class="child-row" data-select="${c.id}"><span class="node-icon ${c.kind}">${c.kind==='material'?'VT':c.kind==='component'?'CK':'SP'}</span><span><strong>${esc(c.name)}</strong><small>${c.kind==='material'?esc(c.materialId):`${c.children?.length||0} thành phần`}</small></span><b>× ${num(c.qty)}</b><span>›</span></button>`).join('')||empty('Chưa có thành phần','Gọi mã vật tư hoặc chọn mẫu có sẵn.')}</div><div class="add-row">${btn('+ Vật tư','add-material',`data-parent="${n.id}"`)}${n.kind==='product'?btn('+ Cấu kiện','add-component',`data-parent="${n.id}"`):''}${btn('Gọi mẫu','pick-template',`data-parent="${n.id}"`)}</div></div><div class="panel visual-panel">${viewer(n)}</div></div>`)+
  renderOperations(n)+`<div class="node-summary"><div><span>Khối lượng phôi</span><strong>${num(r.weight)} kg</strong></div><div><span>Diện tích phôi · tổng ${num(r.count)} ${esc(n.unit||'đơn vị')}</span><strong>${num(r.area)} m²</strong><small>${num(r.count?r.area/r.count:0,4)} m² / ${esc(n.unit||'đơn vị')}</small></div><div><span>Giá vật tư theo phương án</span><strong>${money(r.material)} ₫</strong></div><div><span>Chi phí nguyên công</span><strong>${money(r.ops)} ₫</strong></div></div>`;}
function renderMaterialDetail(n){const m=n.spec,shape=C.shapeInfo(m),vars={...n.dims,...m.props},row=result.rows.find(r=>r.id===n.id);const keys=shape.input.slice();if(m.shape==='sheet')for(const k of ['H','F','D'])if(new RegExp(`\\b${k}\\b`).test(n.ruleSpec.width+' '+n.ruleSpec.length))keys.push(k);return `<div class="panel"><div class="panel-head"><div><h2>Thông tin từ mã vật tư</h2><p>Kế thừa quy cách và đơn giá đã chọn cho báo giá này</p></div>${btn('Đổi mã vật tư','swap-material',`data-id="${n.id}"`)}</div><div class="spec-strip"><span>${esc(m.group)}</span><strong>${esc(specText(m))}</strong><span class="mono">${technicalStage()?'':money(m.price)+' ₫/'+esc(m.unit)}</span></div><div class="panel-body">${m.shape==='piece'?`<div class="notice">Vật tư tính theo ${esc(m.unit)}. Nhập định mức tại ô số lượng phía trên.</div>`:`<div class="section-label">KÍCH THƯỚC THỰC TẾ CHO BÁO GIÁ <span>mm</span></div><div class="dimension-fields">${keys.map(k=>`<label class="field"><span>${{L:'Chiều dài L',W:'Chiều rộng W',H:'Chiều cao H',F:'Mép gấp F',D:'Đường kính D'}[k]||k}</span><input type="number" min="${['F','H'].includes(k)?0:1}" max="100000" step="any" data-dimension="${k}" value="${esc(vars[k])}"></label>`).join('')}</div><label class="field"><span>Quy tắc khai triển</span><select data-rule>${db.rules.filter(r=>r.shape===(m.shape==='sheet'?'sheet':'bar')).map(r=>`<option value="${r.id}" ${r.id===n.rule?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><div class="formula-box"><div><span>Dài khai triển</span><code>${esc(n.ruleSpec.length)}</code><strong>${row?num(row.geometry.length):'?'} mm</strong></div>${m.shape==='sheet'?`<div><span>Rộng khai triển</span><code>${esc(n.ruleSpec.width)}</code><strong>${row?num(row.geometry.width):'?'} mm</strong></div>`:''}</div><p class="help-text">Khổ vật tư mua: ${num(m.stockL)}${m.shape==='sheet'?' × '+num(m.stockW):''} mm. Khai triển là kích thước của phôi cần cắt; được tính riêng cho từng dòng.</p>`}</div></div>`;}
function renderOperations(n){const r=result.nodes[n.id];return `<section class="panel"><div class="panel-head"><div><h2>Nguyên công thực hiện</h2><p>Chọn phương án riêng cho ${n.kind==='product'?'sản phẩm':n.kind==='component'?'cấu kiện':'vật tư'} này</p></div>${btn('+ Nguyên công','add-op',`data-id="${n.id}"`)}</div>${n.ops?.length?`<div class="table-scroll"><table><thead><tr><th>Nguyên công</th><th>Thực hiện</th><th>Cơ sở tính</th><th class="right">Đơn giá</th><th class="right">Thành tiền</th><th></th></tr></thead><tbody>${n.ops.map((op,i)=>{const rate=db.quote.ratesSnapshot.find(x=>x.id===op.id),x=r.ownOps[i];return `<tr><td><strong>${esc(operationDisplayName(rate))}</strong></td><td><select class="compact" data-op-mode="${i}"><option value="inside" ${op.mode==='inside'?'selected':''}>Tại xưởng</option><option value="outside" ${op.mode==='outside'?'selected':''}>Thuê ngoài</option></select></td><td>${['kg','m²'].includes(x.unit)?`<span class="mono">${num(x.basis)} ${x.unit}</span>`:`<input class="compact small-number" aria-label="Định mức ${esc(operationDisplayName(rate))}" type="number" min="0" step="any" data-op-amount="${i}" value="${op.amount}"> ${x.unit}/đv`}</td><td class="right mono">${money(x.rate)}</td><td class="right mono">${money(x.cost)}</td><td>${btn('×','remove-op',`data-index="${i}" aria-label="Xóa nguyên công"`,'square quiet')}</td></tr>`;}).join('')}</tbody></table></div>`:`<div class="muted-row">Chưa khai báo nguyên công ở cấp này.${n.children?.length?' Chi phí của cấp con vẫn được cộng đầy đủ.':''}</div>`}</section>`;}
// Preserve the original box-face 3D interaction; geometry now responds to selected BOM data.
function viewer(n){return renderModelViewer(n);}
function setup3d(){setupModelViewers();}
function stockMap(g,s,index){const sheet=g.spec.shape==='sheet',l=g.layout;
 const triangles=s.placements.some(p=>p.polygon),count=s.placements.length;
 const circles=s.placements.some(p=>p.circle);
 const pieces=circles?`<svg viewBox="0 0 ${l.stockL} ${l.stockW}" style="position:absolute;inset:0;width:100%;height:100%" role="img" aria-label="Sơ đồ ${count} tấm tròn, có chừa mạch cắt">${s.placements.map(p=>`<circle data-circle-piece cx="${p.x+p.l/2}" cy="${p.y+p.w/2}" r="${p.l/2}" fill="${esc(p.color||'#3568aa')}" stroke="white" stroke-width="1" vector-effect="non-scaling-stroke"><title>${esc(p.label)} · D0 ${num(p.l)} mm</title></circle><text x="${p.x+p.l/2}" y="${p.y+p.w/2}" text-anchor="middle" dominant-baseline="middle" fill="white" font-size="${p.l/13}">Ø ${num(p.l)}</text>`).join('')}</svg>`:triangles?`<svg viewBox="0 0 ${l.stockL} ${l.stockW}" style="position:absolute;inset:0;width:100%;height:100%" role="img" aria-label="Sơ đồ ${count} phôi theo biên dạng, có chừa mạch cắt"><title>${count} phôi theo biên dạng trên tấm ${index+1}</title>${s.placements.map(p=>{const points=p.polygon||[[p.x,p.y],[p.x+p.l,p.y],[p.x+p.l,p.y+p.w],[p.x,p.y+p.w]],cx=points.reduce((v,q)=>v+q[0],0)/points.length,cy=points.reduce((v,q)=>v+q[1],0)/points.length;return `<polygon data-polygon-piece ${points.length===3?'data-triangle-piece':''} points="${points.map(q=>q.join(',')).join(' ')}" fill="${esc(p.color||'#3568aa')}" stroke="white" stroke-width="1" vector-effect="non-scaling-stroke"><title>${esc(p.label)} · ${num(p.l)} × ${num(p.w)} mm${p.pairId?' · ghép cặp':''}</title></polygon><text x="${cx}" y="${cy}" text-anchor="middle" dominant-baseline="middle" fill="white" font-size="${Math.min(p.l,p.w)/13}">${num(p.l)} × ${num(p.w)}</text>`;}).join('')}</svg>`:s.placements.map(p=>`<span class="cut-piece" title="${esc(p.label)}: ${num(p.l)}${sheet?' × '+num(p.w):''} mm" style="left:${p.x/l.stockL*100}%;top:${sheet?p.y/l.stockW*100:0}%;width:${p.l/l.stockL*100}%;height:${sheet?p.w/l.stockW*100:100}%;background:${p.color}"><span>${num(p.l)}${sheet?' × '+num(p.w):''}</span></span>`).join('');
 return `<div class="stock-item"><div class="stock-caption"><strong>${sheet?'Tấm':'Thanh'} ${index+1}</strong><span>${count} chi tiết</span></div><div class="stock-map ${sheet?'sheet':'bar'}" style="${sheet?`aspect-ratio:${l.stockL}/${l.stockW}`:''}" aria-label="${sheet?'Tấm':'Thanh'} ${index+1}, ${count} chi tiết">${pieces}${remnantOverlay(g,index)}</div></div>`;
}
function renderWaste(){return renderRemnantWaste();}
function renderMass(){return `<div class="section-toolbar"><div><h2>Bảng rà soát khối lượng & diện tích</h2><p>Kết quả được tổng hợp từ các mã vật tư trong từng sản phẩm.</p></div>${btn('Xuất CSV','export-mass')}</div><div class="notice">Trong demo: phôi = lượng chi tiết cần cắt; vật tư = lượng mua theo khổ, phân bổ theo nhu cầu. Chọn tận dụng phần dư không làm giảm lượng vật tư cần mua. Diện tích phôi tấm là một mặt; nguyên công sơn dùng diện tích bề mặt hai mặt.</div><div class="panel table-scroll"><table><thead><tr><th>Sản phẩm / mã vật tư</th><th>Khai triển (mm)</th><th class="right">SL</th><th class="right">KL phôi (kg)</th><th class="right">KL vật tư (kg)</th><th class="right">DT phôi (m²)</th><th class="right">DT vật tư (m²)</th></tr></thead><tbody>${db.quote.products.map(p=>`<tr class="group-row"><td colspan="7">${esc(p.name)} <span>× ${num(p.qty)}</span></td></tr>${result.rows.filter(r=>r.productId===p.id).map(r=>`<tr><td><span class="mono blue">${esc(r.spec.id)}</span><small class="subtext">${esc(r.path.at(-1)||r.label)}</small></td><td class="mono">${r.spec.shape==='piece'?'Theo đơn vị':num(r.geometry.length)+(r.spec.shape==='sheet'?' × '+num(r.geometry.width):'')}</td><td class="right mono">${num(r.count)}</td><td class="right mono">${r.spec.shape==='piece'?'Không áp dụng':num(r.geometry.weight)}</td><td class="right mono">${r.spec.shape==='piece'?'Không áp dụng':num(r.purchasedWeight)}</td><td class="right mono">${r.spec.shape==='piece'?'Không áp dụng':num(r.geometry.blankArea)}</td><td class="right mono">${r.spec.shape==='piece'?'Không áp dụng':num(r.purchasedArea)}</td></tr>`).join('')}`).join('')}</tbody></table></div>`;}
