  duplicate:el=>{const id=el.dataset.id,source=C.findNode(db.quote.products,id),quote=db.quote;if(!source)return;openDialog('Nhân bản dòng',`<p>Từ: <strong>${esc(source.name)}</strong></p>${field('Tên bản sao','name',(source.name+' (bản sao)').slice(0,200),'text','required maxlength="200"')}<p>Giữ cấu thành, số lượng, kích thước và công đoạn. Bạn có thể chỉnh riêng bản sao sau khi tạo.</p>`,'Tạo bản sao',f=>{const name=String(f.get('name')||'').trim();if(!name)throw Error('Nhập tên cho bản sao.');if(db.quote!==quote||!C.findNode(db.quote.products,id))throw Error('Dòng gốc đã thay đổi. Mở lại thao tác nhân bản nhé.');saveAndClose(()=>{function insert(nodes){const i=nodes.findIndex(n=>n.id===id);if(i>=0){const clone=C.cloneNode(nodes[i]);clone.name=name;delete clone.namePattern;nodes.splice(i+1,0,clone);selected=clone.id;return true;}return nodes.some(n=>n.children&&insert(n.children));}insert(db.quote.products);},'Đã tạo bản sao: '+name);});const input=$('#dialog [name=name]');input?.focus();input?.select();},
